$ErrorActionPreference='Stop'
$root=Resolve-Path (Join-Path $PSScriptRoot '..'); $temp=Join-Path $env:TEMP "installer-helper-$PID"; try {
  $dist=Join-Path $root 'apps\dim-sum-atlas\dist\squirrel-windows'; $setup=@(Get-ChildItem $dist -Filter 'Dim-Sum-Atlas-*.exe' -File); if($setup.Count -eq 1){Import-Module Microsoft.PowerShell.Utility; $savedAuto=$PSModuleAutoLoadingPreference; try{$PSModuleAutoLoadingPreference='None'; Remove-Module Microsoft.PowerShell.Security -ErrorAction SilentlyContinue; $s=& (Join-Path $PSScriptRoot 'get-installer-signature.ps1') -Dist $dist}catch{throw "Explicit security-module import failed with module autoload disabled: $($_.Exception.Message)"}finally{$PSModuleAutoLoadingPreference=$savedAuto}; if($s -ne 'NotSigned'){throw 'Existing setup did not report NotSigned.'}}
  $missing=Join-Path $temp 'missing\squirrel-windows'; New-Item -ItemType Directory -Force $missing | Out-Null; $caught=$false; try{& (Join-Path $PSScriptRoot 'get-installer-signature.ps1') -Dist $missing | Out-Null}catch{$caught=$true}; if(-not $caught){throw 'Missing setup was accepted.'}
  $multi=Join-Path $temp 'multi\squirrel-windows'; New-Item -ItemType Directory -Force $multi | Out-Null; Set-Content (Join-Path $multi 'Dim-Sum-Atlas-a.exe') x; Set-Content (Join-Path $multi 'Dim-Sum-Atlas-b.exe') x; $caught=$false; try{& (Join-Path $PSScriptRoot 'get-installer-signature.ps1') -Dist $multi | Out-Null}catch{$caught=$true}; if(-not $caught){throw 'Multiple setup files were accepted.'}
  $fixture=Join-Path $temp 'fresh\squirrel-windows'; New-Item -ItemType Directory -Force $fixture | Out-Null; $sentinel=Join-Path $temp 'sentinel'; Set-Content $sentinel start; $base=(Get-Date).ToUniversalTime(); [IO.File]::SetLastWriteTimeUtc($sentinel,$base); foreach($n in @('Dim-Sum-Atlas-0.1.1-win-x64.exe','RELEASES','dim-sum-atlas-0.1.1-full.nupkg','installer-manifest.json')){$f=Join-Path $fixture $n; Set-Content $f old; [IO.File]::SetLastWriteTimeUtc($f,$base.AddMinutes(-1))}; $caught=$false; try{& (Join-Path $PSScriptRoot 'assert-installer-fresh.ps1') -Sentinel $sentinel -Dist $fixture | Out-Null}catch{$caught=$true}; if(-not $caught){throw 'Stale fixture was accepted.'}; foreach($n in @('Dim-Sum-Atlas-0.1.1-win-x64.exe','RELEASES','dim-sum-atlas-0.1.1-full.nupkg','installer-manifest.json')){[IO.File]::SetLastWriteTimeUtc((Join-Path $fixture $n),$base.AddMinutes(1))}; & (Join-Path $PSScriptRoot 'assert-installer-fresh.ps1') -Sentinel $sentinel -Dist $fixture | Out-Null
  $outside=Join-Path $env:TEMP 'sibling-prefix-outside'; $caught=$false; try{& (Join-Path $PSScriptRoot 'assert-installer-fresh.ps1') -Sentinel $sentinel -Dist $outside | Out-Null}catch{$caught=$true}; if(-not $caught){throw 'Escaped fixture was accepted.'}; Write-Output 'PASS installer helper regression'
} finally {Remove-Item $temp -Recurse -Force -ErrorAction SilentlyContinue}
